import{_ as e,o,c as a,a2 as r}from"./chunks/framework.ChIlRNAd.js";const u=JSON.parse('{"title":"User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),s={name:"en/guide/index.md"};function n(d,t,i,l,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="user-guide" tabindex="-1">User Guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User Guide&quot;">​</a></h1><p>Nid manages and archives your Gmail mailboxes from your own server (NAS, home server). This guide follows the app&#39;s layout: one page per screen.</p><hr><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Screen</th><th>Address</th><th>What it is for</th></tr></thead><tbody><tr><td><a href="./overview.html"><strong>Overview</strong></a></td><td><code>/overview</code></td><td>Account status, top senders, suggestions, running jobs</td></tr><tr><td><a href="./mails.html"><strong>Mail</strong></a></td><td><code>/mails</code></td><td>Search, select and act on your mails in bulk, with undo</td></tr><tr><td><a href="./cleanup.html"><strong>Cleanup</strong></a></td><td><code>/cleanup</code></td><td>Senders &amp; newsletters, large mails &amp; attachments</td></tr><tr><td><a href="./rules.html"><strong>Rules &amp; labels</strong></a></td><td><code>/rules</code></td><td>Automatic rules, Gmail labels, templates</td></tr><tr><td><a href="./archives.html"><strong>Archives</strong></a></td><td><code>/archives</code></td><td>Local copy on the NAS: search, reader, sharing, trash, retention</td></tr><tr><td><a href="./activity.html"><strong>Activity</strong></a></td><td><code>/activity</code></td><td>Every task started, live</td></tr><tr><td><a href="./settings.html"><strong>Settings</strong></a></td><td><code>/settings/…</code></td><td>Account, Security, Gmail accounts, Notifications &amp; webhooks, Data</td></tr><tr><td><a href="./attachments.html"><strong>Attachments</strong></a></td><td><code>/attachments</code></td><td>Full attachment list (from the ⌘K palette)</td></tr><tr><td><a href="./notifications.html"><strong>Notifications</strong></a></td><td>bell + Settings</td><td>In-app notifications, toasts, webhooks</td></tr><tr><td><a href="./admin.html"><strong>Administration</strong></a></td><td><code>/admin</code></td><td>Users, instance settings, audit (admins)</td></tr><tr><td><a href="./mcp-server.html"><strong>MCP Server</strong></a></td><td>—</td><td>Drive Nid from an AI assistant</td></tr></tbody></table><p>New to Nid? Start with <a href="./first-steps.html"><strong>First Steps</strong></a>.</p><hr><h2 id="finding-your-way-around" tabindex="-1">Finding your way around <a class="header-anchor" href="#finding-your-way-around" aria-label="Permalink to &quot;Finding your way around&quot;">​</a></h2><h3 id="on-desktop" tabindex="-1">On desktop <a class="header-anchor" href="#on-desktop" aria-label="Permalink to &quot;On desktop&quot;">​</a></h3><ul><li><strong>Sidebar</strong> on the left: logo, <strong>Collapse sidebar</strong> button (<code>Ctrl+B</code> / <code>⌘B</code>), <strong>Gmail Account</strong> selector, <strong>Search…</strong> button, then the entries Overview, Mail, Cleanup, Rules &amp; labels, Archives, Activity, Settings. Administrators also get an <strong>Administration</strong> group with <strong>Admin</strong>.</li><li><strong>Counters</strong> next to the entries: number of mails in the account (Mail), number of active rules (Rules &amp; labels), &quot;N running&quot; (Activity).</li><li><strong>Header</strong>: the <a href="./notifications.html">notifications</a> bell and the user menu (avatar): <strong>Language</strong>, <strong>Dark mode</strong>, <strong>Log out</strong>.</li></ul><h3 id="on-mobile" tabindex="-1">On mobile <a class="header-anchor" href="#on-mobile" aria-label="Permalink to &quot;On mobile&quot;">​</a></h3><p>The header keeps the bell and the avatar; the avatar menu also holds the <strong>Gmail Account</strong> choice. A bar at the bottom of the screen leads to <strong>Home</strong> (Overview), <strong>Mail</strong>, <strong>Cleanup</strong>, <strong>Archives</strong> and <strong>More</strong>.</p><p>The <strong>More</strong> page holds the rest:</p><ul><li><strong>Tools</strong>: Rules &amp; labels, Activity (with the number of running tasks);</li><li><strong>Settings</strong>: the five sections, each with a summary (&quot;2FA on&quot;, &quot;1 action required&quot;, &quot;Import, export&quot;…);</li><li><strong>Administration</strong> (admins only): &quot;Instance admin&quot;;</li><li>at the bottom: &quot;Signed in as …&quot; and <strong>Sign out of Nid</strong>.</li></ul><h3 id="command-palette" tabindex="-1">Command palette <a class="header-anchor" href="#command-palette" aria-label="Permalink to &quot;Command palette&quot;">​</a></h3><p><code>⌘K</code> (Mac) or <code>Ctrl+K</code> opens the &quot;Go to…&quot; palette: every navigation page, the <strong>New rule</strong> action, and under <strong>Other pages</strong> the <a href="./attachments.html">Attachments</a> page.</p><h3 id="old-addresses" tabindex="-1">Old addresses <a class="header-anchor" href="#old-addresses" aria-label="Permalink to &quot;Old addresses&quot;">​</a></h3><p>Old pages redirect to their new place: <code>/dashboard</code>, <code>/analytics</code>, <code>/insights</code> → Overview; <code>/unified</code> → Mail, &quot;All accounts&quot;; <code>/saved-searches</code> → Mail; <code>/unsubscribe</code> → Cleanup; <code>/expiration</code> → Rules &amp; labels, Labels tab; <code>/archive</code> → Archives; <code>/sharing</code> → Archives, Shares tab; <code>/jobs</code> → Activity; <code>/privacy</code> → Settings › Account; <code>/ops</code> → Settings › Data.</p>',18)])])}const m=e(s,[["render",n]]);export{u as __pageData,m as default};
